presets.css:
/* ===== 高性能磨砂气泡（替代原来高开销版本） ===== */
.chat-msg.is-them .chat-bubble,
.chat-msg.is-me .chat-bubble {
  background: rgba(255, 255, 255, 0.08) !important;   /* 加一层淡淡底色，降低对模糊的依赖 */
  backdrop-filter: blur(8px) !important;               /* 32px → 8px，GPU 压力降 90% */
  -webkit-backdrop-filter: blur(8px) !important;
  border: 1px solid rgba(255, 255, 255, 0.35) !important;
  border-radius: 28px !important;
  padding: 4px 16px !important;
  box-shadow: 0 0 20px rgba(255, 255, 255, 0.06) !important;
  overflow: visible !important;
  text-shadow:
    0 0 10px #ffffff,
    0 0 25px #ffffff !important;                      /* 4 层 → 2 层，发光依旧明显 */
  letter-spacing: 0.5px !important;
  line-height: 1.4 !important;
}

html[data-theme="dark"] .chat-msg.is-them .chat-bubble,
html[data-theme="dark"] .chat-msg.is-me .chat-bubble {
  background: rgba(255, 255, 255, 0.05) !important;
  border-color: rgba(255, 255, 255, 0.18) !important;
  box-shadow: none !important;
  text-shadow:
    0 0 10px rgba(255, 255, 255, 0.8),
    0 0 25px rgba(255, 255, 255, 0.5) !important;
}

/* ===== 底栏和顶栏也顺便降一下 ===== */
.chat-thread .chat-thread-pill {
  backdrop-filter: none !important;
  -webkit-backdrop-filter: none !important;
}

/* ===== 性能优化 ===== */
.chat-thread .chat-msg {
  contain: layout style paint !important;
  content-visibility: auto !important;
  contain-intrinsic-size: 60px !important;
}
.chat-thread .chat-ava,
.chat-thread .chat-bubble {
  transform: translateZ(0) !important;
  backface-visibility: hidden !important;
}

/* ==========================================================
3. 消息布局 + 头像
========================================================== */
.chat-msg {
  display: flex !important;
  align-items: center !important;
}
.chat-msg .avatar-wrap {
  align-self: center !important;
  flex-shrink: 0 !important;
  margin-top: 0 !important;
}

/* 角色消息顶部对齐（避免头像因气泡高度变化而移动） */
.chat-thread .chat-msg.is-them {
  align-items: flex-start !important;
}
.chat-thread .chat-msg.is-them .chat-ava {
  align-self: flex-start !important;
  margin-top: 0 !important;
  transform: none !important;
}

/* ==========================================================
4. 图片下移（只影响气泡内图片，头像天然不受影响）
========================================================== */
.chat-thread .chat-msg.is-them .chat-bubble img {
  display: block !important;
  margin-top: 26px !important;
  margin-bottom: 0 !important;
}

/* ==========================================================
5. 时间戳隐藏 + 系统通知
========================================================== */
.chat-msg-time {
  display: none !important;
}

.chat-msg-timestamp,
.chat-thread-notice {
  margin-top: 35px !important;
  margin-bottom: 15px !important;
  color: #999999 !important;
}
html[data-theme="dark"] .chat-msg-timestamp,
html[data-theme="dark"] .chat-thread-notice {
  color: #777777 !important;
}

/* ==========================================================
6. 隐藏昵称
========================================================== */
.chat-msg-name,
.chat-msg.is-them .chat-msg-header,
[class*="msg-name"],
[class*="nickname"],
[class*="name-tag"] {
  display: none !important;
}

/* ==========================================================
7. 气泡内文字颜色
========================================================== */
.chat-msg .chat-bubble,
.chat-msg .chat-bubble * {
  color: #000000 !important;
}
html[data-theme="dark"] .chat-msg .chat-bubble,
html[data-theme="dark"] .chat-msg .chat-bubble * {
  color: #ffffff !important;
}

/* ==========================================================
8. 输入栏（半透明 + 颜文字 + 占位符）
========================================================== */
.chat-compose-bar {
  background: rgba(255, 255, 255, 0.25) !important;
  backdrop-filter: none !important;
  -webkit-backdrop-filter: none !important;
  border: 1px solid rgba(255, 255, 255, 0.30) !important;
  border-radius: 999px !important;
  box-shadow: 0 4px 20px rgba(0, 0, 0, 0.04) !important;
  position: relative !important;
}
html[data-theme="dark"] .chat-compose-bar {
  background: rgba(60, 60, 65, 0.40) !important;
  border-color: rgba(255, 255, 255, 0.10) !important;
  box-shadow: 0 4px 24px rgba(0, 0, 0, 0.20) !important;
}

/* + 号隐藏，颜文字显示在左侧 */
.chat-compose-plus {
  opacity: 0 !important;
  pointer-events: auto !important;
}
.chat-compose-bar::before {
  content: "ᗜ֊ᗜ" !important;
  position: absolute !important;
  left: 16px !important;
  top: 50% !important;
  transform: translateY(-50%) !important;
  font-size: 16px !important;
  color: #999999 !important;
  z-index: 999 !important;
  pointer-events: none !important;
}
html[data-theme="dark"] .chat-compose-bar::before {
  color: #aaaaaa !important;
}

/* 语音和发送按钮保留 */
.chat-compose-icon.is-voice,
.chat-compose-icon.is-send.ready {
  opacity: 1 !important;
  pointer-events: auto !important;
}

/* 输入框透明 + 隐藏原生 placeholder */
.chat-compose-input {
  background: transparent !important;
}
.chat-compose-bar .chat-compose-input::placeholder,
.chat-compose-bar .chat-compose-input::-webkit-input-placeholder,
.chat-compose-bar .chat-compose-input::-moz-placeholder,
.chat-compose-bar .chat-compose-input:-ms-input-placeholder {
  color: transparent !important;
  opacity: 0 !important;
  font-size: 0 !important;
  visibility: hidden !important;
}

/* 模拟占位符 */
.chat-compose-bar:not(:focus-within)::after {
  content: "我在一万颗星星中找到了你" !important;
  position: absolute !important;
  left: 65px !important;
  top: 50% !important;
  transform: translateY(-50%) !important;
  color: #999999 !important;
  font-size: 13px !important;
  pointer-events: none !important;
  z-index: 5 !important;
  white-space: nowrap !important;
}
.chat-compose-bar:focus-within::after {
  content: none !important;
}

/* ==========================================================
9. 顶栏（透明 + 颜文字）
========================================================== */
.chat-thread .chat-thread-pill {
  background: transparent !important;
  backdrop-filter: none !important;
  -webkit-backdrop-filter: none !important;
  border: 1px solid rgba(255, 255, 255, 0.15) !important;
  box-shadow: none !important;
  position: relative !important;
}
html[data-theme="dark"] .chat-thread .chat-thread-pill {
  border-color: rgba(255, 255, 255, 0.08) !important;
}

/* 原图标透明但保留点击 */
.chat-thread .chat-back,
.chat-thread .chat-thread-head-more,
.chat-thread .chat-thread-head-xinsheng {
  opacity: 0 !important;
  pointer-events: auto !important;
  width: 36px !important;
  height: 36px !important;
  margin: 0 !important;
  padding: 0 !important;
  background: transparent !important;
  position: relative !important;
  z-index: 10 !important;
}

/* 颜文字装饰 */
.chat-thread .chat-thread-pill::before {
  content: "•﹏•" !important;
  position: absolute !important;
  left: 16px !important;
  top: 50% !important;
  transform: translateY(-50%) !important;
  font-size: 16px !important;
  color: #999999 !important;
  z-index: 999 !important;
  pointer-events: none !important;
}
.chat-thread .chat-thread-pill::after {
  content: "˵>ㅿ<˵" !important;
  position: absolute !important;
  right: 16px !important;
  top: 50% !important;
  transform: translateY(-50%) !important;
  font-size: 16px !important;
  color: #999999 !important;
  z-index: 999 !important;
  pointer-events: none !important;
}
html[data-theme="dark"] .chat-thread .chat-thread-pill::before,
html[data-theme="dark"] .chat-thread .chat-thread-pill::after {
  color: #aaaaaa !important;
}

/* ==========================================================
10. 图标统一灰色
========================================================== */
:root {
  --icon-gray: #888888;
}
.chat-thread [class*="icon"],
.chat-compose [class*="icon"],
.chat-thread .chat-back,
.chat-thread .chat-thread-head-more,
.chat-thread .chat-thread-head-xinsheng,
.chat-compose-plus,
.chat-compose-icon {
  color: var(--icon-gray) !important;
}
.chat-thread [class*="icon"]::before,
.chat-thread [class*="icon"]::after,
.chat-compose [class*="icon"]::before,
.chat-compose [class*="icon"]::after,
.chat-compose-icon::before,
.chat-compose-icon::after {
  color: var(--icon-gray) !important;
}
.chat-thread svg,
.chat-thread svg *,
.chat-compose svg,
.chat-compose svg * {
  fill: var(--icon-gray) !important;
  stroke: var(--icon-gray) !important;
}

/* ==========================================================
11. 性能优化
========================================================== */
.chat-thread .chat-msg {
  contain: layout style paint !important;
  content-visibility: auto !important;
  contain-intrinsic-size: 60px !important;
}
.chat-thread .chat-ava,
.chat-thread .chat-bubble {
  transform: translateZ(0) !important;
  backface-visibility: hidden !important;
}
/* ===== 强力隐藏原生 placeholder（加强版） ===== */
.chat-compose-bar input::placeholder,
.chat-compose-bar textarea::placeholder,
.chat-compose-bar .chat-compose-input::placeholder,
.chat-compose-bar input::-webkit-input-placeholder,
.chat-compose-bar textarea::-webkit-input-placeholder,
.chat-compose-bar .chat-compose-input::-webkit-input-placeholder {
  color: transparent !important;
  -webkit-text-fill-color: transparent !important;  /* 关键：覆盖 WebView 默认填充色 */
  opacity: 0 !important;
  font-size: 0 !important;
  visibility: hidden !important;
}
